import fs from 'node:fs';
const rows=JSON.parse(fs.readFileSync('content/os-l9-before-20261118.json','utf8'));
const drafts=new Map();
function add(indices,topic,text){for(const i of indices){if(drafts.has(i))throw Error('duplicate '+i);drafts.set(i,{category:topic,explanation:text});}}
add([0,45],'記憶體保護','判斷重點是「起點與長度」。Base 記錄最小合法實體位址，Limit 記錄可用範圍大小，兩者共同界定程序能使用的記憶體。\n\n例如 base = 1000、limit = 200，合法邏輯位址為 0～199，轉換後是實體位址 1000～1199。PC／IR 管理下一條指令與目前指令；索引暫存器／堆疊指標用於運算與堆疊位置；頁／段相關暫存器屬其他轉譯結構，都不是此題的基底與界限組合。');
add([1,4],'記憶體保護','記憶體保護像替各程序劃出可使用的房間：一個程序不能任意修改其他程序或核心的資料。它能防止越界寫入破壞執行結果，支援程序之間隔離，也保護作業系統。\n\n因此「程序互不影響」「作業系統不受使用者程序影響」及「確保程式正確運作」符合目標。這裡的正確運作指防止非法記憶體存取干擾，並不保證程式沒有邏輯錯誤；提高 CPU 時脈則與此保護機制無關。');
add([2,3],'記憶體保護','先檢查邏輯位址，再加上基底：合法條件是 0 ≤ logical address < limit，通過後 physical address = base + logical address。\n\n例如 limit = 100，從 0 起算只有 0～99 共 100 個位置，所以等於 limit 已越界，不能使用 ≤ limit。Base 是實體起點，不能拿邏輯位址是否小於 base 來判定合法；負位址也不在此範圍內。');
add([5,7,8,55],'記憶體保護','依序填 base／limit。Base（基底）表示可用實體區域的起點，Limit（限制）表示區域長度。\n\n例如 base = 4000、limit = 500，邏輯位址 120 小於 500，故可轉為實體位址 4120；邏輯位址 500 已越界。記成「base 決定從哪裡開始，limit 決定有多大」，不要把 limit 誤當成最後一個實體位址。');
add([6,9,66],'記憶體保護','Valid-invalid 位元用來判斷某個頁面是否屬於程序可合法使用的位址範圍，主要目的為記憶體保護。\n\n存取時先取得頁表項目，再檢查有效性與權限；合法才繼續轉譯，非法則觸發例外交由作業系統處理。這個位元本身不負責快取資料、控制 I/O 或建立共享。注意有效性與「頁面目前是否在 RAM」可能由不同欄位表示，不能把所有 invalid 都解讀為讀磁碟即可解決。填空使用 valid-invalid。');
add([10,11,22,127],'位址繫結','載入時才知道程式要放在哪個實體起點，因此編譯器必須先產生 relocatable code（可重定位程式碼）。載入器確定起點後，才能調整需要重定位的位址。\n\n例如程式內某資料位於起點後 40 位元組，載入到 1000 時對應 1040，改載到 3000 時則是 3040。Absolute code 已固定位置，不適合這種需求；static／dynamic 描述其他特性，virtual code 也不是這組繫結階段使用的標準對應名稱。填空填 relocatable。');
add([12,13],'位址繫結','編譯時若已知道程式的實體放置位置，就可產生 absolute code（絕對程式碼），把相關位址固定下來。\n\n例如編譯時假定起點是 1000，某資料就直接使用 1040；若之後改放到 3000，這個固定位置便不再適用，通常須重新編譯。Relocatable code 是位置留待後續調整的版本，dynamic／virtual 並不是此階段對應的程式碼類型。');
add([14,15,20,21],'位址繫結','題幹關鍵是「執行期間仍可搬移」。程序目前在某個實體位置，搬移後相同邏輯位址必須指向新位置，因此要等每次執行存取時才完成映射，也就是 execution time。\n\n例如邏輯位址 20 原先映到 1020，搬移後可改映到 3020，程式仍使用 20。Compile time 與 load time 都太早固定位置；linking time 處理模組與符號的連接，無法單靠它支援持續搬移。填空填 execution。');
add([16,18],'位址繫結','載入時繫結的流程是：編譯器先留下可重定位位址 → 載入器選定實體起點 → 修正位址並開始執行。因此「產生可重定位程式碼」「最後實體位址在載入時確定」成立。\n\n單就這種繫結而言，不必靠 MMU 在每次存取時重新定位；這不代表整個作業系統沒有 MMU 或不需要任何保護硬體。若執行中還要任意搬移，須採執行時繫結，因此「執行時可搬移」不屬此階段特性。');
add([17,19],'位址繫結','執行時繫結把邏輯位址到實體位址的轉換交給 MMU，在存取當下依目前映射決定位置。程序可在執行期間搬移，位址映射與程式內容也必須允許重定位。\n\n可想成程式一直使用同一組房間編號，由管理員更新它實際對應哪棟樓。「MMU 處理轉換」「允許搬移」「可重定位」符合此模型；生成固定實體位址的 absolute code 則與這種彈性相衝突。');
add([23,26,38,41],'連續配置與碎片','外部碎片指可用空間散在已配置區塊之間，總量足夠卻湊不成要求的連續區域，常見於連續記憶體配置。\n\n例如三個空洞分別有 3、4、3 KB，合計 10 KB，仍放不下需要連續 8 KB 的程序。分頁允許分散到各頁框，避免此連續空間限制；雜湊頁表與倒置頁表則是頁表組織方式。若題幹已寫 fragmentation，空格只填 external。');
add([24,27,28,30,35,42,47,78],'連續配置與碎片','內部碎片是「已分配區塊裡面」沒用到的空間。分頁以固定大小頁框配置，程序最後一頁往往無法填滿。\n\n例如頁面 4 KB、資料共 10 KB，要配置 3 頁共 12 KB，最後剩 2 KB，即 internal fragmentation。總空閒量足夠卻不相鄰描述的是外部碎片；純分段採可變大小段，典型問題是外部碎片。Swapping 是搬出／載回，dynamic linking 是連結方式；stack overflow 與 memory leak 也不是區塊尾端浪費的名稱。填空填 internal。');
add([25],'記憶體保護','Base register（基底暫存器）保存程序所在區域的起始實體位址。合法邏輯位址通過界限檢查後，會與 base 相加。\n\n例如起點 2000、邏輯位址 80，實體位址為 2080。Limit register 保存的是可用長度；index register 協助索引運算；program counter 指向接下來要執行的指令，都不是本題問的區域起點。');
add([29,32],'連續配置與碎片','先把程序切成等大的 pages，再把每頁放到任一可用 frame，頁表負責記錄對應。因此程序在實體記憶體中可以不連續，也不用再找到一整塊大空洞，能消除這種配置的外部碎片。\n\n例如 3 頁資料可分放 frame 2、8、15。最後一頁仍可能用不滿，故不能選「消除內部碎片」。分頁確實可搭配逐頁權限，但「簡化記憶體保護」不是這題問的解除連續空間限制的直接效果。');
add([31,36,39,40],'連續配置與碎片','處理外部碎片有兩個思路：compaction 搬移已用區塊，把分散空洞合併；paging 改用等大頁框配置，讓程序不必占一整塊連續空間。\n\n例如 3 KB 與 5 KB 空洞經壓縮可合成 8 KB。First-fit 只決定先挑哪個洞，仍會留下零散空間；純 segmentation 的段也需各自連續，仍可能有外部碎片。壓縮需要支援執行時重定位，且有搬移成本；填空填 compaction。');
add([33,37],'連續配置與碎片','碎片分成 internal 與 external。Internal 是已分配區塊內沒用滿，例如拿到 8 KB 只用 6 KB；external 是空閒空間散在區塊之間，例如兩個 4 KB 空洞不能滿足連續 6 KB 要求。\n\n前者關注「區塊裡面」，後者關注「區塊外面」。Logical fragmentation、virtual fragmentation 不是這組記憶體配置的標準二分名稱。不同連續配置方法可能有不同碎片問題，不能只靠「連續」就判定只有其中一種。');
add([34,51],'非連續配置方式','Paging 把程序切成等大頁，各頁可放到不相鄰的 frame；hierarchical paging 在此基礎上把頁表分層；segmentation 則讓不同邏輯段分別配置，因此這三者都不要求整個程序占一塊連續實體區域。\n\n例如程式碼段與資料段可放在不同位置。注意純分段通常仍要求「每個段內」連續；Contiguous Allocation 則要求程序使用連續區域，和題目要找的類型相反。');
add([43,80],'分頁與 TLB','填 logical。程式使用的是 logical address space（邏輯位址空間）；分頁將它的每個 page 分別映射到實體 frame，所以它在實體記憶體中的配置可以不連續。\n\n例如程式看到連續的邏輯第 0、1、2 頁，實際可能在 frame 7、2、11。這不代表程式看到的邏輯位址也必須斷裂，而是「邏輯上連續、實體可分散」。看到題幹的 in physical memory，應把這兩個視角分開。');
add([44,48],'位址繫結','MMU（Memory Management Unit）是執行位址轉譯的硬體單元，把程式產生的邏輯／虛擬位址映射到實體位址，並配合權限檢查。\n\n例如分頁位址中的頁號經頁表映到 frame，再加頁內偏移形成實體位址。CPU 是包含多種功能的處理器整體；ALU 負責算術邏輯，FPU 負責浮點運算。題目要的是專門負責映射的單元，因此選 MMU。');
add([46,99,104,106],'分段','Segmentation（分段）依程式的邏輯意義切分記憶體，例如程式碼、資料與堆疊，各單元稱 segments，大小可以不同。\n\n像把一本書依章節分開，各章長短不一；paging 則像把內容切成固定張數的紙包。Swapping 描述程序在 RAM 與後備儲存之間搬移；contiguous allocation 描述放置方式，都不是以邏輯單元看待程式的定義。填空使用複數 segments。');
add([49,112],'載入、交換與連結','一般程式要從磁碟載入 main memory（主記憶體），CPU 才能透過記憶體階層取得指令與資料執行。可把磁碟想成保存檔案的倉庫，主記憶體是執行時的工作區。\n\nCache 與 registers 會進一步保存近期指令、資料與運算狀態，但容量與管理角色不同，並非本題從磁碟載入程式的主要目的地。Auxiliary memory 屬輔助儲存，仍是保存資料的地方。');
add([50,108,113,115,118,120],'載入、交換與連結','Dynamic loading（動態載入）是在常式真正被呼叫時才把它載入記憶體，未使用的部分先留在磁碟。\n\n例如程式有很大的錯誤處理模組，正常執行時不呼叫它，就不用讓它占 RAM。這能提高記憶體利用率，支援總體較大的程式；但仍須能容納當下要執行的部分。它不會縮小磁碟上原始程式的全部內容、不保證提高 I/O 速度，也無法消除外部碎片。靜態載入則較早載入，靜態連結處理的是模組合併。');
add([52,53],'頁表結構','線性頁表通常每個虛擬頁都預留一個表項，64 位元位址空間太大時，表本身也會非常龐大。\n\n用完整 64 位元位址與 4 KB 頁作概念計算：頁數 = 2^64 ÷ 2^12 = 2^52；若每項 8 bytes，頁表將達 2^55 bytes。即使只實作較少位址位元，密集平鋪也可能浪費大量空間。因此原因是邏輯空間龐大與頁表占用過多記憶體；並非頁表必須放磁碟，也不能只以存取速度慢解釋其容量問題。');
add([54,57],'位址繫結','填 address binding（位址繫結）。它表示建立程式位址與實際記憶體位置之間的對應，依完成時機分為編譯時、載入時與執行時。\n\n例如程式內的某資料位置，必須最後對應到可存取的實體位置；若程序還能搬移，就延到執行時轉譯。注意 address binding 是「建立對應的機制／過程」，MMU 是能協助執行時轉譯的硬體，兩者不能互換名稱。');
add([56,61,62,72],'分頁與 TLB','TLB（Translation Lookaside Buffer）是位址轉譯的小型高速快取，保存最近用過的虛擬頁到實體 frame 對應。\n\n例如上一個存取已知道第 5 頁在 frame 12，下一次同頁的存取若 TLB 命中，就不必重新走完整頁表。它只快取部分表項，並不保存整張頁表；交換由作業系統處理，頁面大小由架構與設定決定，這些都不是 TLB 的主要用途。填空依要求使用大寫 TLB。');
add([58,60,67,75],'分頁與 TLB','邏輯記憶體切成 pages（頁），實體記憶體切成相同大小的 frames（頁框）。先有邏輯頁號，再由頁表找出實體頁框號。\n\n例如邏輯 page 3 可以放在實體 frame 9，兩者容量相等，所以一整頁能完整放入一個頁框。Segments 是可變大小的邏輯段，sectors 通常是儲存裝置的單位。問實體區塊時回答 frames；兩空依序填 pages／frames。');
add([59,63,65],'分頁與 TLB','邏輯位址分為 page number（頁號）和 page offset（頁內偏移）。頁號用來查頁表、找 frame；偏移用來選該頁內的位元組，轉譯前後保持相同。\n\n例如頁面 1024 bytes、邏輯位址 2500：2500 = 2 × 1024 + 452，所以頁號為 2、偏移為 452。若頁表說第 2 頁在 frame 7，實體位址就是 7 × 1024 + 452 = 7620。Frame number 是查表結果，base address 是表或區域起點，都不是輸入頁表的邏輯頁索引。');
add([64,77,83,89,91,94],'頁表結構','倒置頁表（inverted page table）以實體 frame 為單位，每個框架對應一個表項，記錄占用它的程序 ID 與虛擬頁號。\n\n例如 RAM 只有 1000 個 frames，就依這 1000 個實體位置建表，而不用替每個程序所有可能的虛擬頁各建一項，能降低頁表空間需求。代價是查找要比對程序與頁號，未必更快。外部碎片是分配單位與連續性造成的問題，不是倒置表帶來的獨有改進；分層／雜湊是其他表組織方式。兩空依序填 inverted／frame。');
add([68,71],'分頁與 TLB','TLB miss 只是高速轉譯快取沒有該項，先查主記憶體中的頁表，取得有效映射後，再把對應補入 TLB，之後重試存取。\n\n例如頁面早已在 RAM，只因很久沒用而不在 TLB，查頁表即可，不必讀磁碟。只有另外發現頁面不在記憶體等缺頁狀況，才可能需要 I/O；TLB 已滿時才需替換舊項，因此「一定刪除舊項」與「一定載入磁碟頁」都不是每次 miss 的必要步驟。');
add([69,70,74,76],'分頁與 TLB','TLB 要回答「哪個程序的哪個虛擬頁，對應哪個實體 frame」，因此需辨識頁號、框架號，並可用程序／位址空間識別標籤區分不同程序。\n\n例如兩個程序都使用第 3 頁，實際可能指向不同 frames，不能只比頁號。題目把這個識別欄位稱為 Process ID，填空用 PID；實際處理器常用 ASID／PCID 等位址空間標籤。Page offset 是原位址帶來的頁內位置，不必逐項存進 TLB。');
add([73,82],'分頁與 TLB','依序填 logical／physical。CPU 產生程式看到的 logical address（邏輯位址），MMU 依頁表映射轉成 physical address（實體位址），才能選中 RAM 的位置。\n\n例如邏輯第 2 頁映到 frame 8，轉換時只替換頁號，頁內偏移不變。不同程序可以產生相同邏輯位址，卻各自映到不同實體位置；不要把程式看到的編號與 RAM 實際位置視為同一個值。');
add([79,81],'記憶體保護','填 protected（受保護的）。頁表決定程序能讀寫哪些實體位置，因此頁表本身也要存放在使用者程序不能任意修改的記憶體區域。\n\n例如惡意程序若能把自己的頁表項目改成核心所在 frame，即可能繞過隔離。TLB miss 後查表時，硬體／核心依規則讀取這些受保護資料；受保護不代表頁表不存在於 RAM，也不代表一定要放在 TLB。');
add([84,85,86,87,95,96],'頁表結構','Hierarchical paging（分層分頁）把大型頁表本身分頁，透過上層索引找到下層頁表，再由下層項目找到資料 frame。沒有使用到的位址區域可不配置對應的下層表。\n\n兩級例子是：外層頁號 → 內層頁號 → 頁內偏移。因此它適合表示大型、稀疏的虛擬空間，位址也會拆成多個部分；不是只靠一張平鋪表、不是把整張表放 TLB，也不是改成 segmentation。填空填 paging。');
add([88],'頁表結構','一般每程序頁表中的 PTE 需要 frame number 來決定資料所在位置，protection bits 來限制讀／寫／執行，並有 valid-invalid 等狀態位元來判斷映射是否有效。\n\n轉譯時先查出表項，檢查有效性與權限，再組合 frame 和偏移。Process ID 通常由目前選用哪個程序頁表判定，不需每個一般 PTE 都再寫一次；倒置頁表或帶標籤 TLB 則可能另外保存程序識別資訊。');
add([90,92],'頁表結構','倒置頁表把全系統各實體 frame 的使用者記在同一張表。要找某次存取，需以「Process ID ＋ virtual page number」辨認是哪個程序的哪一頁。\n\n例如程序 10 的第 4 頁與程序 20 的第 4 頁不能當成同一項。Page offset 在找到 frame 後才用來定位頁內資料，不是搜尋映射的識別條件；表的基底位置只告訴硬體表放在哪裡，也不能單靠它辨認目標頁。');
add([93,97],'頁表結構','填 lookup（查找）。雜湊頁表先用虛擬頁號計算雜湊值，找到對應桶，再沿該桶的鏈結串列逐項比對完整的頁號與必要識別資訊，找到後取出實體 frame。\n\n因為不同頁號可能得到相同雜湊值，不能只看桶號就直接認定命中；鏈結串列正是用來處理這種碰撞。頁內偏移保持不變，最後和找到的 frame 組成實體位址。');
add([98,100,103,105],'分段','分段位址由 segment number（段號）與 offset（段內偏移）組成。先用段號選段表項，檢查 0 ≤ offset < limit，再計算 physical address = base + offset。\n\n例如第 2 段 base = 5000、limit = 600，offset = 120 合法，得到實體位址 5120；offset = 600 則越界。Page／frame 是分頁用語；base／limit 是表中描述段的位置與大小，不是程式輸入的這對邏輯位址。填空依序填 segment number／offset。');
add([101,102],'分段','段表的一項要描述「段從哪開始、長多大、允許怎樣存取」，因此包含 base address、limit 與 protection bits。\n\n例如 base = 8000、limit = 300，只讀權限：段內偏移 100 可讀取實體位址 8100，但寫入仍會被拒絕；偏移 300 已超出大小。Frame number 是等大分頁框架的編號，純分段以可變長度區域為單位，不能拿它取代段的起點與界限。');
add([107,111,124,125],'載入、交換與連結','Stub 是替真正程式庫常式暫時站位的一小段程式碼。第一次呼叫時，它協助找到目標常式的位址，必要時請載入器載入，再讓後續呼叫直接導向該常式。\n\n可想成櫃台先幫你找到服務人員，之後知道位置就直接前往。Buffer 是資料緩衝區，frame 是分頁的實體區塊，block 是泛稱區塊，都不是這種呼叫代理程式。填 stub。這個「以替代碼定位常式」的描述通常屬動態連結，即使題幹使用動態載入用語，也應依其行為辨識。');
add([109,116,126],'載入、交換與連結','Swapping 會把暫時不用的程序從主記憶體搬到 backing store（後備儲存），需要時再載回。傳統模型的後備儲存通常是 disk。\n\n例如 RAM 不足時先把等待中的程序換出，讓別的程序使用空間。Registers 與 cache 容量小且用途不同，無法作為整個程序的交換區。Auxiliary memory 是較廣的輔助儲存名稱，backing store 則精確指出供換出／載回使用的角色。兩空依序填 backing store／disk。');
add([110,114,123,128],'載入、交換與連結','Dynamic linking 把程式庫常式的連接／符號解析延到 execution time（執行時間）。程式開始執行後，可透過 stub 或動態連結器取得目標常式的位置。\n\n編譯時間主要把原始碼翻成機器碼；載入時間是把程式放入記憶體；啟動只是執行初期的一個時點。實際系統可在程式啟動時解析，也可第一次呼叫時才解析，所以本題要選涵蓋這些情況的執行時間。填空填 execution。');
add([117,121],'載入、交換與連結','動態連結讓執行檔不必各自複製完整程式庫內容，多個程序也能共享可重入、唯讀的程式庫程式碼，因此可縮小執行檔並節省重複載入的空間。\n\n本題還採按需解析／載入的情境，常式可在需要時才載入；實際系統也可能啟動時就載入相依程式庫，故這不是所有動態連結的必然行為。內部碎片來自配置單位沒有用滿，改用動態連結無法保證消除它。');
add([119,122],'載入、交換與連結','交換的主要時間包含把程序寫到後備儲存、之後讀回主記憶體，以及保存／恢復程序狀態等切換成本。\n\n例如需傳輸 100 MB，裝置有效速度為每秒 200 MB，單趟約 0.5 秒，來回約 1 秒，還沒計入等待與其他開銷。這說明傳輸量越大，成本通常越高。TLB miss 是轉譯快取沒有命中的成本，可能另行發生，但不屬此題列的換出、換入與上下文切換這組主要成本。');
add([129,137,140],'架構案例：ARM／Intel','PAE 擴大的是可使用的實體位址範圍。32 位元位址共有 2^32 bytes，也就是 4 GiB；支援 PAE 的系統可用較寬的實體位址管理超過此容量的 RAM。\n\n這不會讓每個 32 位元程序自動得到超過 4 GiB 的線性位址空間，單一程序要使用更多資料仍須配合作業系統提供的映射方式。Dynamic loading 是按需載入，inverted page table 是表結構，address binding 是建立位址對應，都不是這項實體位址擴充技術。填空填 pae。');
add([130,131],'架構案例：ARM／Intel','這組選項中的答案是 4 KB 與 16 KB，兩者都可作為 ARM 架構中的頁面／轉譯粒度；其餘組合不是本題指定的配對。\n\n但 ARM 有不同架構版本，不能把這兩個大小背成所有版本唯一的選擇：AArch64 的粒度還包含 64 KB；舊式 ARM short-descriptor 的 small page／large page 則是 4 KB／64 KB。判斷時先確認架構版本與描述格式，再分辨 page 與 section／block。');
add([132,134],'架構案例：ARM／Intel','本題選取支援 4 KB／16 KB 頁面、較小頁面的兩級查表，以及 1 MB／16 MB 大型映射這三段描述；「只有單一級 TLB」不成立，TLB 可依處理器實作分成指令／資料或多級。\n\n需分清版本：這組敘述混合了不同 ARM 格式。舊式 short-descriptor 的 1 MB 稱 section、16 MB 稱 supersection，小頁查表使用兩級；AArch64 支援 4／16／64 KB 粒度，但不能把所有這些特性直接視為同一種固定頁表格式。理解每個名詞的條件，才能避免記成所有 ARM 通用的規則。');
add([133,135,139],'架構案例：ARM／Intel','以四級 x86-64 分頁與 4 KB 頁面計算：每級索引 9 位，共 4 × 9 = 36 位；頁內偏移 12 位，所以線性位址轉譯合計 36 + 12 = 48 位。常見映射大小包括 4 KB、2 MB 與 1 GB；長模式分頁需要啟用 PAE，不能選不支援 PAE。\n\n48 是此四級模型的答案，不等於 x86-64 永遠只能使用 48 位；支援五級分頁的系統可用 57 位線性位址。虛擬位址寬度與實體位址寬度也應分開。填空填 48。');
add([136,138],'架構案例：ARM／Intel','填 sections。題幹用 sections 概括舊式 ARM 的大型區塊映射；精確區分是 1 MB 稱 section、16 MB 稱 supersection。\n\n因為 16 MB = 16 × 1 MB，可把 supersection 理解為更大的映射單位。這些大型映射讓一筆描述可涵蓋較大連續區域，減少細碎的頁表項目；但它們屬特定 ARM 描述格式，不能直接套用到所有 AArch64 的 page／block 命名。');
if(drafts.size!==rows.length)throw Error('uncovered '+rows.map((q,i)=>i).filter(i=>!drafts.has(i)));
const content=JSON.parse(fs.readFileSync('assets/os-content-explanations.json','utf8'));
const records=[];const identity=q=>JSON.stringify([String(q.type??''),String(q.stem??q.q??''),q.options??q.opts??[],String(q.answer??q.a??''),q.images??[]]);
rows.forEach((q,i)=>{const d=drafts.get(i);const record={identity:identity(q),sourceExplanation:q.explanation||'',...d};const old=content.questions[q.id]||{};const versions=(old.versions||[]).filter(v=>v.identity!==record.identity);content.questions[q.id]={...old,versions:[...versions,record]};records.push({id:q.id,...record,type:q.type,answer:q.answer,stem:q.stem,oldCategory:q.category});});
fs.writeFileSync('assets/os-content-explanations.json',JSON.stringify(content,null,2)+'\n');
let html=fs.readFileSync('os.html','utf8');html=html.replace(/(<script id="course-content-explanations"[^>]*>)[\s\S]*?(<\/script>)/,(_,a,b)=>a+JSON.stringify(content).replace(/<\//g,'<\\/')+b);fs.writeFileSync('os.html',html);
const topicOrder=JSON.parse(fs.readFileSync('assets/os-l9-curation.json','utf8')).categoryOrder;
const rank={'單選題':0,'多選題':1,'填空題':2};const sorted=records.map((q,i)=>({...q,i})).sort((a,b)=>topicOrder.indexOf(a.category)-topicOrder.indexOf(b.category)||rank[a.type]-rank[b.type]||a.i-b.i);
const report={date:'2026-11-18',course:'os',unit:'L9',scope:'目前完整快照中的 141 題；原題、選項、答案與 ID 保留，重寫解析並調整主題。',topicOrder,typeOrder:Object.keys(rank),statistics:{questions:rows.length,types:Object.fromEntries(Object.keys(rank).map(t=>[t,rows.filter(q=>q.type===t).length])),reclassified:records.filter(q=>q.oldCategory!==q.category).length},records};
fs.writeFileSync('content/os-l9-explanation-curation-20261118.json',JSON.stringify(report,null,2)+'\n');fs.writeFileSync('content/os-l9-question-order.json',JSON.stringify({date:report.date,course:'os',unit:'L9',topicOrder,typeOrder:Object.keys(rank),originalOrder:rows.map(q=>q.id),orderedIds:sorted.map(q=>q.id),reclassified:records.filter(q=>q.category!==q.oldCategory).map(q=>({id:q.id,from:q.oldCategory,to:q.category}))},null,2)+'\n');
console.log(JSON.stringify(report.statistics));
